// The night bus on an old screen: the room graded to sodium streetlight (orange highs,
// teal-black shadows, brake-light reds kept red), shown on a tired tube: soft along the lines,
// faint scanlines, a slow hum bar rolling up and a fine static over it all. The kick is the bus
// passing under a lamp. param[0] static, param[1] sodium.
float aspect = resolution.x / resolution.y;
vec3 Y = vec3(0.299, 0.587, 0.114);
vec3 cam = source(uv);

// An old tube smears a little along its lines: two taps either side, horizontally only.
float sx = 0.0025;
vec3 soft = cam * 0.4 + (source(uv + vec2(sx, 0.0)) + source(uv - vec2(sx, 0.0))) * 0.2
          + (source(uv + vec2(sx * 2.5, 0.0)) + source(uv - vec2(sx * 2.5, 0.0))) * 0.1;

// Sodium: shadows to night and teal, highs to orange and lamp, strong reds to brake light.
float l = dot(soft, Y);
vec3 dark = mix(palette[0], palette[1], smoothstep(0.0, 0.35, l));
vec3 lit = mix(palette[2], palette[3], smoothstep(0.6, 1.0, l));
vec3 graded = mix(dark, lit, smoothstep(0.2, 0.7, l));
float red = clamp(soft.r - max(soft.g, soft.b), 0.0, 1.0);
graded = mix(graded, palette[4] * (0.55 + l), smoothstep(0.28, 0.5, red));
graded = mix(soft, graded, param[1]);

// Passing streetlights: a soft band of lamp light slides across; the kick brightens it.
float sweep = fract(uv.x * 0.5 - time * 0.3) - 0.5;
float lamp = exp(-sweep * sweep * 18.0);
graded += palette[3] * lamp * (0.06 + 0.3 * audio.beat) * (0.3 + l);

// Scanlines: about 240 lines whatever the resolution, a gentle dip between them.
float lines = 0.5 + 0.5 * cos(uv.y * 240.0 * 6.2832);
graded *= 1.0 - 0.12 * lines;

// The hum bar: a wide, faint brighter band rolling slowly up the screen.
float roll = fract(uv.y - time * 0.07) - 0.5;
graded *= 1.0 + 0.05 * exp(-roll * roll * 40.0);

// Static: fine snow, new every frame, a little brighter in the shadows where a weak signal
// shows it most. Zero-mean, so it does not lift the picture.
vec2 px = floor(uv * resolution);
float snow = hash(px + vec2(floor(time * 60.0) * 1.37, 0.0)) - 0.5;
float amp = mix(0.03, 0.16, param[0]) * (1.0 - 0.5 * l);
graded += snow * amp;

// The tube's corners fall off a little.
vec2 c = (uv - 0.5) * vec2(aspect, 1.0);
graded *= 1.0 - 0.25 * smoothstep(0.45, 1.0, length(c));

return mix(cam, graded, strength);

// Light trails: what is bright streams sideways, as lights slide past a bus window, and fades.
// The hi-hats chop the trails into dashes: while the hats are loud the trail is dimmed hard
// seven and a half times a second, over a few frames rather than at once. param[0] trails.
vec3 now = source(uv);
vec2 drift = vec2(0.0035, 0.0006) * (0.5 + param[0]);
vec3 before = lastFrame(uv + drift);
float decay = mix(0.8, 0.965, param[0]);
float gate = 1.0 - 0.45 * audio.high * step(0.5, fract(time * 7.5));
// A max, never a sum: the feedback's gain stays below 1 and cannot build up.
vec3 streak = max(now, before * decay * gate);
return mix(now, streak, strength);
